import{_ as e,o as a,c as i,ag as d}from"./chunks/framework.DaCm-iTo.js";const u=JSON.parse('{"title":"Attribute Definitions","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/attribute/attributes.md","filePath":"en/modules/attribute/attributes.md","lastUpdated":null}'),r={name:"en/modules/attribute/attributes.md"};function s(o,t,n,l,c,p){return a(),i("div",null,[...t[0]||(t[0]=[d(`<h1 id="attribute-definitions" tabindex="-1">Attribute Definitions <a class="header-anchor" href="#attribute-definitions" aria-label="Permalink to &quot;Attribute Definitions&quot;">​</a></h1><p>Attribute files are stored under <code>attributes/*.yml</code>. Each file usually defines one attribute, including how the value is identified, clamped, displayed, parsed, and used by combat or other modules.</p><h2 id="important-fields" tabindex="-1">Important fields <a class="header-anchor" href="#important-fields" aria-label="Permalink to &quot;Important fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>Unique attribute id used by other modules.</td></tr><tr><td><code>display_name</code></td><td>Display name and lore matching key. Defaults to <code>id</code>.</td></tr><tr><td><code>value_kind</code></td><td>Value style, such as <code>FLAT</code>, <code>PERCENT</code>, <code>CHANCE</code>, <code>REGEN</code>, <code>RESOURCE</code>, or <code>DERIVED</code>.</td></tr><tr><td><code>target_type</code></td><td>Target system, such as <code>GENERIC</code>, <code>DAMAGE</code>, <code>RESOURCE</code>, or <code>VANILLA</code>.</td></tr><tr><td><code>target_id</code></td><td>Damage type id, resource id, or vanilla attribute id depending on <code>target_type</code>.</td></tr><tr><td><code>mmoitems_stat</code></td><td>MMOItems stat id mapping, used to bridge attribute reads when MMOItems is installed.</td></tr><tr><td><code>default_value</code></td><td>Default base value.</td></tr><tr><td><code>min_value</code> / <code>max_value</code></td><td>Optional clamps.</td></tr><tr><td><code>allow_negative</code></td><td>Whether negative values are allowed.</td></tr><tr><td><code>priority</code></td><td>Lore parsing priority. Higher values match earlier.</td></tr><tr><td><code>lore_format_id</code></td><td>Linked lore format definition.</td></tr><tr><td><code>lore_pattern</code> / <code>lore_patterns</code></td><td>Regex patterns used for lore parsing.</td></tr><tr><td><code>attribute_power</code></td><td>Weight used when calculating total power.</td></tr><tr><td><code>tags</code></td><td>Optional attribute tags (e.g. <code>DEBUFF</code>). Used by the MythicMobs <code>emaki_attribute_add_tag</code> / <code>emaki_attribute_clear_tag</code> mechanics to add or clear temporary attributes in bulk. Case-insensitive.</td></tr><tr><td><code>temporary_stack_mode</code></td><td>Stack behavior when the same temporary attribute (same <code>effect_id</code>) is applied again: <code>REPLACE</code> (default) overwrites, <code>STACK</code> adds value and remaining duration. A skill-provided <code>stack_mode</code> overrides this.</td></tr><tr><td><code>parent_attribute</code></td><td>Whether this definition is a parent attribute used by the attribute-points system. Parent attributes may also enter item snapshots from lore or EA attribute PDC and expand <code>child_bonuses</code>.</td></tr><tr><td><code>child_bonuses</code></td><td>Map of child attribute contributions per allocated parent point. Child targets must exist and must not be parent attributes.</td></tr><tr><td><code>description</code></td><td>Description text (string or list) usable in GUIs or help output.</td></tr></tbody></table><h2 id="parent-attributes-and-attribute-points" tabindex="-1">Parent attributes and attribute points <a class="header-anchor" href="#parent-attributes-and-attribute-points" aria-label="Permalink to &quot;Parent attributes and attribute points&quot;">​</a></h2><p>Parent attributes power the attribute-points system. A player allocates available points into attributes marked with <code>parent_attribute: true</code>; the allocated point count contributes to the parent attribute itself and each <code>child_bonuses</code> entry contributes additional child-attribute values per point. Player data is stored under <code>data/parent_attributes/&lt;UUID&gt;.yml</code> with <code>available_points</code>, <code>reset_points</code>, and <code>allocations</code>.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">strength</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">display_name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;red&gt;Strength&#39;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">value_kind</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">FLAT</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">parent_attribute</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">child_bonuses</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  physical_attack</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2.0</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  max_health_bonus</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5.0</span></span></code></pre></div><p>Parent attributes appear in traces and final snapshots and can be read like normal numeric attributes from item lore or the <code>ea_attribute.ea_attributes</code> PDC. An item parent value keeps its own ID and also contributes to each child attribute ID through <code>child_bonuses</code>. The same parent attribute from lore and PDC is added first, then expanded. The runtime has no fixed parent or child IDs and creates no fallback parent attribute when definitions are absent; every relationship comes from the currently loaded attribute YAML. EmakiItem <code>variables</code> remain text placeholders only and do not automatically become EA attributes. If <code>child_bonuses</code> points to a missing attribute or another parent attribute, <code>/ea lint</code> reports the configuration issue.</p><h2 id="value-kinds" tabindex="-1">Value kinds <a class="header-anchor" href="#value-kinds" aria-label="Permalink to &quot;Value kinds&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Value</th><th>Description</th></tr></thead><tbody><tr><td><code>FLAT</code></td><td>Fixed additive value.</td></tr><tr><td><code>PERCENT</code></td><td>Percentage value. Lore parsing handles <code>%</code> suffixes.</td></tr><tr><td><code>CHANCE</code></td><td>Chance-like percentage value.</td></tr><tr><td><code>REGEN</code></td><td>Regeneration rate.</td></tr><tr><td><code>RESOURCE</code></td><td>Resource capacity contribution.</td></tr><tr><td><code>DERIVED</code></td><td>Derived attribute calculated from other values.</td></tr></tbody></table><h2 id="target-types" tabindex="-1">Target types <a class="header-anchor" href="#target-types" aria-label="Permalink to &quot;Target types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Value</th><th>Description</th></tr></thead><tbody><tr><td><code>GENERIC</code></td><td>General-purpose attribute.</td></tr><tr><td><code>DAMAGE</code></td><td>Participates in a <code>damage_types/*.yml</code> damage pipeline.</td></tr><tr><td><code>RESOURCE</code></td><td>Affects resource maximums or recovery.</td></tr><tr><td><code>VANILLA</code></td><td>Syncs to a vanilla Minecraft/Bukkit attribute.</td></tr></tbody></table><h2 id="ranged-random-values" tabindex="-1">Ranged random values <a class="header-anchor" href="#ranged-random-values" aria-label="Permalink to &quot;Ranged random values&quot;">​</a></h2><p>Current Attribute parsing supports ranged contributions. A range keeps the minimum, maximum, and resolved actual value in the snapshot contribution, which is useful for random attack rolls or random percentage bonuses.</p><p>Example:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ea_attributes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  physical_attack</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;10-20&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  physical_crit_rate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;5%-12%&quot;</span></span></code></pre></div><p>Guidelines:</p><ul><li>Numeric ranges are suitable for attack, defense, and resource-capacity attributes.</li><li>Percentage ranges are suitable for <code>PERCENT</code> and <code>CHANCE</code> attributes. Keep one consistent scale across the system; do not mix <code>0.15</code> and <code>15</code> for the same meaning.</li><li>Debug output should inspect the min, max, and actual resolved value when a contribution comes from a range.</li><li>New equipment systems should still prefer PDC payloads over lore-only parsing.</li></ul><h2 id="lore-parsing" tabindex="-1">Lore parsing <a class="header-anchor" href="#lore-parsing" aria-label="Permalink to &quot;Lore parsing&quot;">​</a></h2><p><code>lore_pattern</code> and <code>lore_patterns</code> can use these variables:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Expands to</th></tr></thead><tbody><tr><td><code>%Key%</code> / <code>%key%</code></td><td>Escaped <code>display_name</code>.</td></tr><tr><td><code>%Value%</code> / <code>%value%</code></td><td>Numeric capture group.</td></tr></tbody></table><p>Lore parsing is mainly for compatibility with old or external items. For new Emaki item flows, prefer explicit PDC payloads from EmakiItem, Forge, Strengthen, or Gem. Text parsing is sensitive to colors, language, and formatting, can be altered by players or other plugins, and may mis-match similar lines.</p><h3 id="built-in-lore-format-priority" tabindex="-1">Built-in lore format priority <a class="header-anchor" href="#built-in-lore-format-priority" aria-label="Permalink to &quot;Built-in lore format priority&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Format ID</th><th>Priority</th></tr></thead><tbody><tr><td><code>default_percent</code></td><td>100</td></tr><tr><td><code>default_regen</code></td><td>80</td></tr><tr><td><code>default_resource</code></td><td>60</td></tr><tr><td><code>default_flat</code></td><td>50</td></tr></tbody></table><p>Higher priority formats are matched first when several formats could match the same lore line.</p>`,25)])])}const b=e(r,[["render",s]]);export{u as __pageData,b as default};
